def qaoa_maxcut_ansatz(G, beta, gamma):
    if G is None:
        edges = ((0, 3), (0, 4), (1, 3), (1, 4), (2, 3), (2, 4))
        n_qubits = 5
    else:
        edges = tuple(G.edges)
        n_qubits = len(G.nodes)
    if beta is None:
        beta = [1.4544410433286077] * 5
    if gamma is None:
        gamma = [1.4544410433286077] * 5
    dev = qml.device("default.qubit", wires=n_qubits, shots=None)

    @qml.qnode(dev)
    def circuit():
        for wire in range(n_qubits):
            qml.Hadamard(wires=wire)
        for layer in range(len(beta)):
            for control, target in edges:
                qml.CNOT(wires=[control, target])
                qml.RZ(2 * gamma[layer], wires=target)
                qml.CNOT(wires=[control, target])
            for wire in range(n_qubits):
                qml.RX(2 * beta[layer], wires=wire)
        return qml.probs(wires=list(reversed(range(n_qubits))))

    return circuit()

