def HHL_4x4():
    A = 0.5 * np.array([[3, 0, 0, -1], [0, 7, -1, 0], [0, -1, 7, 0], [-1, 0, 0, 3]], dtype=complex)
    t = np.pi / 4
    dev = qml.device("default.qubit", wires=6, shots=None)

    @qml.qnode(dev)
    def circuit():
        qml.Hadamard(wires=4)
        qml.Hadamard(wires=1)
        qml.Hadamard(wires=2)
        qml.Hadamard(wires=3)
        for idx in range(3):
            qml.ctrl(qml.QubitUnitary(expm(1j * A * t * (2 ** idx)), wires=[4, 5]), control=1 + idx)
        qml.adjoint(qml.QFT)(wires=[3, 2, 1])
        for k, cs in [(1.0, (1, 0, 0)), (2.0, (0, 1, 0)), (3.0, (1, 1, 0)), (4.0, (0, 0, 1))]:
            qml.ctrl(qml.RY(2 * np.arcsin(1 / k), wires=0), control=[1, 2, 3], control_values=cs)
        qml.QFT(wires=[3, 2, 1])
        for idx in range(3):
            qml.ctrl(qml.QubitUnitary(expm(-1j * A * t * (2 ** (2 - idx))), wires=[4, 5]), control=3 - idx)
        qml.Hadamard(wires=1)
        qml.Hadamard(wires=2)
        qml.Hadamard(wires=3)
        return qml.probs(wires=[5, 4, 0])

    return circuit()

