            qml.Hadamard(wires=w)
        qml.CNOT(wires=[2, 4])
        qml.CNOT(wires=[3, 4])
        for w in range(4):
            qml.Hadamard(wires=w)
        return qml.probs(wires=[3, 2, 1, 0])

    return circuit()

