def Qadd():
    """General 8-qubit Cuccaro ripple adder for a = 100, b = 001, c0 = 1.

    Carry-in c0 is wire 0, the b register is on odd wires, the a register on
    even wires; the 4-bit sum (with carry-out on wire 7) is read from wires
    7, 5, 3, 1.
    """
    dev = qml.device("default.qubit", wires=8, shots=None)

    @qml.qnode(dev)
    def circuit():
        qml.PauliX(wires=0)
        qml.PauliX(wires=1)
        qml.PauliX(wires=6)

        def maj(ci, bi, ai):
            qml.CNOT(wires=[ai, bi])
            qml.CNOT(wires=[ai, ci])
            qml.Toffoli(wires=[bi, ci, ai])

        def uma(ci, bi, ai):
            qml.Toffoli(wires=[bi, ci, ai])
            qml.CNOT(wires=[ai, ci])
            qml.CNOT(wires=[ci, bi])

        for i in range(3):
            maj(2 * i, 2 * i + 1, 2 * i + 2)
        qml.CNOT(wires=[6, 7])
        for i in (2, 1, 0):
            uma(2 * i, 2 * i + 1, 2 * i + 2)
        return qml.probs(wires=[7, 5, 3, 1])

    return circuit()

