def qpe_grover00_gate(n_count=3):
    dev = qml.device("default.qubit", wires=n_count + 2, shots=None)

    def grover():
        w0, w1 = n_count, n_count + 1
        qml.PauliX(w0)
        qml.PauliX(w1)
        qml.CZ([w0, w1])
        qml.PauliX(w0)
        qml.PauliX(w1)
        qml.Hadamard(w0)
        qml.Hadamard(w1)
        qml.PauliX(w0)
        qml.PauliX(w1)
        qml.CZ([w0, w1])
        qml.PauliX(w0)
        qml.PauliX(w1)
        qml.Hadamard(w0)
        qml.Hadamard(w1)

    @qml.qnode(dev)
    def circuit():
        for q in range(n_count):
            qml.Hadamard(q)
        qml.Hadamard(n_count)
        qml.Hadamard(n_count + 1)
        for j in range(n_count):
            for _ in range(2 ** j):
                qml.ctrl(grover, control=j)()
                qml.PauliZ(j)
        for i in range(n_count // 2):
            qml.SWAP(wires=[i, n_count - 1 - i])
        for i in range(n_count):
            for j in range(i):
                qml.ControlledPhaseShift(-pi / (2 ** (i - j)), wires=[j, i])
            qml.Hadamard(wires=i)
        return qml.probs(wires=list(reversed(range(n_count))))

    return circuit()

