def quantum_counting_marked_11():
    dev = qml.device("default.qubit", wires=5, shots=None)

    @qml.qnode(dev)
    def circuit():
        def controlled_h(control, target):
            qml.S(wires=target)
            qml.Hadamard(wires=target)
            qml.T(wires=target)
            qml.CNOT(wires=[control, target])
            for _ in range(7):
                qml.T(wires=target)
            qml.Hadamard(wires=target)
            for _ in range(3):
                qml.S(wires=target)

        def controlled_cz(control, a, b):
            qml.Hadamard(wires=b)
            qml.Toffoli(wires=[control, a, b])
            qml.Hadamard(wires=b)

        def controlled_grover(control):
            controlled_cz(control, 3, 4)
            for target in (3, 4):
                controlled_h(control, target)
            qml.CNOT(wires=[control, 3])
            qml.CNOT(wires=[control, 4])
            controlled_cz(control, 3, 4)
            qml.CNOT(wires=[control, 3])
            qml.CNOT(wires=[control, 4])
            for target in (3, 4):
                controlled_h(control, target)

        def inverse_qft(qubits):
            n = len(qubits)
            for i in range(n // 2):
                qml.SWAP(wires=[qubits[i], qubits[n - 1 - i]])
            for i in range(n):
                for j in range(i):
                    qml.ControlledPhaseShift(-pi / (2 ** (i - j)), wires=[qubits[j], qubits[i]])
                qml.Hadamard(wires=qubits[i])

        for wire in range(5):
            qml.Hadamard(wires=wire)
        for control in range(3):
            for _ in range(2 ** control):
                controlled_grover(control)
                qml.PauliZ(wires=control)
        inverse_qft([0, 1, 2])
        return qml.probs(wires=[2, 1, 0])

    return circuit()

